{
  "world_id": "wld_ring_seven",
  "name": "The Seventh Ring",
  "description": "A generation ship crosses the dark with its inhabited tiers arranged as nested rotating rings. The seventh ring has declared independence and severed the elevators that once linked it to the tiers above and below. Its people control their own air, water, and local governance, but isolation threatens the delicate systems that keep their home alive. The ship's founding charter offers no clear answer to whether a ring can leave the common authority, and every day without shared maintenance makes the question more urgent. A peculiar feature of the ship is that its structural ribs carry low-frequency vibrations: crews once used them to detect mechanical faults, but now those same vibrations may carry messages across sealed elevator shafts.",
  "locations": [
    {
      "id": "loc_seventh_habitat",
      "name": "Seventh Habitat",
      "description": "A long residential ring of apartments, communal gardens, and workshops, now governed by its independence council. Its inhabitants have little room to expand and cannot agree on how much to sacrifice for the tiers beyond."
    },
    {
      "id": "loc_crown_lift",
      "name": "Crown Lift Junction",
      "description": "The sealed upper elevator terminus, where severed cables sway in the shaft and old service panels still show the shipwide maintenance network. The council posts guards here, while listeners search for vibration patterns in the walls."
    },
    {
      "id": "loc_water_ledger",
      "name": "Water Ledger Hall",
      "description": "A converted cistern control room containing the ring's allocation records and manual valve maps. Whoever controls its ledgers can decide which neighborhoods receive clean water during shortages."
    },
    {
      "id": "loc_core_exchange",
      "name": "Core Exchange",
      "description": "A shared machinery level beneath the inhabited tiers, reachable only through narrow maintenance crawls. Its heat exchangers and circulation pumps serve every ring, making it the most dangerous place for either side to sabotage or occupy."
    }
  ],
  "factions": [
    {
      "id": "fac_seventh_council",
      "name": "Seventh Ring Council",
      "description": "The elected body that issued the independence declaration. It promises local control but is divided between negotiators seeking a new charter and hardliners who consider reconnection a surrender.",
      "location_ids": [
        "loc_seventh_habitat",
        "loc_water_ledger"
      ]
    },
    {
      "id": "fac_shipwardens",
      "name": "Shipwardens",
      "description": "The shipwide engineering authority, responsible for life support across all tiers. They insist the severed lifts and isolated controls endanger everyone, but their command structure has never given the rings equal representation.",
      "location_ids": [
        "loc_crown_lift",
        "loc_core_exchange"
      ]
    },
    {
      "id": "fac_rib_listeners",
      "name": "Rib Listeners",
      "description": "A loose network of technicians and couriers who read vibrations through the ship's frame. They claim to have found a pattern that may be a message from an unlisted compartment, though neither governing side trusts their interpretation.",
      "location_ids": [
        "loc_crown_lift",
        "loc_core_exchange"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_spin_gravity",
      "statement": "The inhabited rings generate their everyday gravity through rotation; changes in spin must be gradual to avoid injury and structural strain.",
      "category": "physics"
    },
    {
      "id": "rul_closed_ecology",
      "statement": "Air and water are recycled within the ship, and any ring that isolates its supply systems must maintain its own filters and circulation.",
      "category": "technology"
    },
    {
      "id": "rul_shared_charter",
      "statement": "The founding charter assigns life-support maintenance to the shipwide authority but grants each ring a voice in decisions affecting its population.",
      "category": "social"
    },
    {
      "id": "rul_vibration_network",
      "statement": "The structural ribs transmit low-frequency vibration across sealed sections, but only trained listeners can distinguish deliberate patterns from ordinary machinery.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_charter_compromise",
      "name": "The Founding Charter",
      "description": "After the ship's early crews nearly lost a ring to conflicting maintenance orders, they established shared engineering authority alongside local representation. The charter left the meaning of ring sovereignty unresolved.",
      "era": "First generation",
      "location_ids": [
        "loc_core_exchange"
      ]
    },
    {
      "id": "evt_lift_severance",
      "name": "The Lift Severance",
      "description": "Seventh Ring technicians cut the elevator controls after a shipwide order reassigned their water reserves without a council vote. The break prevented immediate intervention and turned a dispute into an independence crisis.",
      "era": "Present",
      "location_ids": [
        "loc_crown_lift",
        "loc_water_ledger"
      ]
    },
    {
      "id": "evt_rib_signal",
      "name": "The Unlisted Rhythm",
      "description": "Listeners detected a repeating sequence in the ship's ribs, unlike known pump and bearing patterns. It appears to originate near the shared machinery, but the source cannot be reached without crossing a contested access route.",
      "era": "Present",
      "location_ids": [
        "loc_crown_lift",
        "loc_core_exchange"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_sovereignty",
      "name": "The Severed Charter",
      "description": "The council treats the lift break as a lawful assertion of self-rule; the Shipwardens call it an unacceptable threat to shared life support. Reopening the route could restore essential cooperation while undoing the council's strongest claim to independence.",
      "faction_ids": [
        "fac_seventh_council",
        "fac_shipwardens"
      ]
    },
    {
      "id": "cnf_water_control",
      "name": "The Water Allocation",
      "description": "The ring's reserves cannot support every neighborhood at its present rate. The council must choose between equitable rationing and protecting the technicians needed to keep its systems running, while the Shipwardens demand access to the allocation records.",
      "faction_ids": [
        "fac_seventh_council",
        "fac_shipwardens"
      ]
    },
    {
      "id": "cnf_untrusted_signal",
      "name": "The Message in the Ribs",
      "description": "The Rib Listeners believe the unexplained rhythm may reveal a hidden compartment or failing system. Both authorities want the discovery contained until they know what it means, putting the listeners at risk if they publish their findings.",
      "faction_ids": [
        "fac_rib_listeners",
        "fac_seventh_council",
        "fac_shipwardens"
      ]
    }
  ]
}
